+static void handle_key(int key) {
+    if (opts.screensaver) return;
+    
+    switch (key) {
+        case 'a':
+            opts.async = !opts.async;
+            break;
+        case 'b':
+            opts.bold = 1;
+            opts.all_bold = 0;
+            opts.no_bold = 0;
+            break;
+        case 'B':
+            opts.all_bold = 1;
+            opts.bold = 0;
+            opts.no_bold = 0;
+            break;
+        case 'n':
+            opts.no_bold = 1;
+            opts.bold = 0;
+            opts.all_bold = 0;
+            break;
+        case '0':
+        case '1':
+        case '2':
+        case '3':
+        case '4':
+        case '5':
+        case '6':
+        case '7':
+        case '8':
+        case '9':
+            opts.delay = key - '0';
+            if (opts.delay < 0) opts.delay = 0;
+            if (opts.delay > MAX_DELAY) opts.delay = MAX_DELAY;
+            break;
+        case '!':
+            set_color(1);  // red
+            break;
+        case '@':
+            set_color(0);  // green
+            break;
+        case '#':
+            set_color(2);  // yellow
+            break;
+        case '$':
+            set_color(3);  // blue
+            break;
+        case '%':
+            set_color(4);  // magenta
+            break;
+        case '^':
+            set_color(5);  // cyan
+            break;
+        case '&':
+            set_color(6);  // white
+            break;
+        case ')':
+            set_color(7);  // black
+            break;
+        case 'q':
+            running = 0;
+            break;
+    }
+}
