+    if (opts.force_term) {
+        setenv("TERM", "linux", 1);
+    }
+    
+    if (opts.tty_fd >= 0) {
+        set_tty(opts.tty_fd);
+    }
+    
+    srand(time(NULL));
+    
+    while (running) {
+        if (opts.rainbow) {
+            current_color = rand() % 8;
+        }
+        
+        if (opts.lambda) {
+            for (int y = 0; y < height; y++) {
+                for (int x = 0; x < width; x++) {
+                    printf("\033[%d;%dH", y + 1, x + 1);
+                    printf("\033[32m\033[1m\033[90m\033[37m\033[0m");
+                    printf("λ");
+                }
+            }
+        } else {
+            update_matrix();
+        }
+        
+        if (opts.chars_change && !opts.old_scroll) {
+            for (int y = 0; y < height; y++) {
+                for (int x = 0; x < width; x++) {
+                    int col = (x + y * width + (rand() % 100)) % (width * height);
+                    draw_line(y, x, col);
+                }
+            }
+        }
+        
+        if (opts.has_message) {
+            message_set = 1;
+            strncpy(message, opts.message, sizeof(message) - 1);
+            message[sizeof(message) - 1] = '\0';
+        }
+        
+        if (opts.lock) {
+            draw_lock_message();
+        }
+        
+        if (opts.has_message) {
+            draw_message();
+        }
+        
+        if (opts.screensaver) {
+            int key = get_key();
+            if (key >= 0) {
+                running = 0;
+            }
+        } else {
+            int key = get_key();
+            if (key >= 0) {
+                handle_key(key);
+            }
+        }
+        
+        usleep(opts.delay * 100000);
+    }
+    
+    set_cursor_visible();
+    restore_tty();
+}
