+static void draw_matrix(int fd) {
+    int height, width;
+    int x, y;
+    int col, row;
+    int i, j;
+    int char_idx;
+    int color_idx;
+    int current_color = 0;
+    
+    getmaxyx(stdscr, height, width);
+    
+    for (y = 0; y < height; y++) {
+        for (x = 0; x < width; x++) {
+            if (y == height - 1) {
+                mvaddch(y, x, ' ');
+                continue;
+            }
+            
+            char_idx = get_random_char();
+            if (char_idx == 0) {
+                mvaddch(y, x, ' ');
+                continue;
+            }
+            
+            if (lambda_mode) {
+                mvaddch(y, x, 0x03BB);
+                continue;
+            }
+            
+            if (old_style) {
+                char_idx = get_random_char_old();
+            }
+            
+            if (char_idx == 0) {
+                mvaddch(y, x, ' ');
+                continue;
+            }
+            
+            if (rainbow_mode) {
+                color_idx = (current_color + x) % 8;
+                current_color = (current_color + 1) % 8;
+            } else {
+                color_idx = 0;
+            }
+            
+            if (only_shadows) {
+                attron(A_REVERSE);
+            } else {
+                attron(COLOR_PAIR(color_idx + 1));
+            }
+            
+            if (all_bold) {
+                attron(A_BOLD);
+            } else if (bold_chars) {
+                if (rand() % 100 < 50) {
+                    attron(A_BOLD);
+                }
+            }
+            
+            mvaddch(y, x, (char)char_idx);
+            attroff(A_BOLD);
+            attroff(COLOR_PAIR(color_idx + 1));
+            attroff(A_REVERSE);
+        }
+    }
+    
+    if (message && !message_set) {
+        int msg_height = 2;
+        int msg_width = strlen(message) + 2;
+        int msg_x = (width - msg_width) / 2;
+        int msg_y = (height - msg_height) / 2;
+        mvaddstr(msg_y, msg_x, message);
+        mvaddstr(msg_y + 1, msg_x, message);
+    }
+}
